class Solution {
  public int xorRegisterTotalReceipt(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    int answer=0;for(int x:out)answer+=x;return answer;
  }
}
